document.addEventListener('DOMContentLoaded', () => {
    const observationForm = document.getElementById('observation-form');
    const observationCountElement = document.getElementById('observation-count');
    const observationsListElement = document.getElementById('observations-list');
    const emptyStateElement = document.getElementById('empty-state');

    let observations = [];

    function updateCount() {
        observationCountElement.textContent = observations.length;
        emptyStateElement.classList.toggle('hidden', observations.length > 0);
    }

    function renderObservations() {
        observationsListElement.innerHTML = '';
        observations.forEach((obs, index) => {
            const card = document.createElement('div');
            card.className = 'observation-card';
            card.innerHTML = `
                <h4>${obs.title}</h4>
                <p><strong>Location:</strong> ${obs.location}</p>
                <p><strong>Note:</strong> ${obs.note}</p>
            `;
            observationsListElement.appendChild(card);
        });
        updateCount();
    }

    observationForm.addEventListener('submit', (e) => {
        e.preventDefault();

        const title = document.getElementById('title').value.trim();
        const location = document.getElementById('location').value.trim();
        const note = document.getElementById('note').value.trim();

        if (title && location && note) {
            const newObservation = {
                title: title,
                location: location,
                note: note,
                timestamp: new Date().toISOString()
            };
            observations.push(newObservation);
            renderObservations();
            observationForm.reset();
        }
    });

    // Initial render (will show empty state)
    renderObservations();
});

